import{createWorld,step,command,metrics,serialize,deserialize,DAY}from'./sim.js';
export const PLAN={version:2,seeds:Array.from({length:20},(_,i)=>41+i),trainingDays:10,followupDays:5,provision:{amount:40,every:240,x:13,y:13},recipient:0,failedSource:'a'};
export function schedule(s,branch,cont=false){if(branch==='provision'&&(s.tick<10*DAY||cont)&&s.tick%240===0)command(s,{type:'food',x:13,y:13,amount:40});step(s);}
export function runSeed(seed,config={},snapshots=false,progress=()=>{}){const rows=[];for(const branch of ['baseline','provision','access','information']){const s=createWorld(seed,config);if(branch==='access')command(s,{type:'bridge'});if(branch==='information')command(s,{type:'reveal',id:0});for(let i=0;i<10*DAY;i++)schedule(s,branch);const before=metrics(s),snapshot=serialize(s);for(const condition of ['unchanged','berry-failure',...(branch==='provision'?['continued-provision','continued-provision+failure']:[])]){const f=deserialize(snapshot);if(condition.includes('failure'))command(f,{type:'failure'});let recovery=null,recoveryAlive=null,worsened=false;for(let i=0;i<5*DAY;i++){schedule(f,branch,condition.startsWith('continued'));if(f.tick%60===0){const m=metrics(f);if(m.medianHunger!==null&&before.medianHunger!==null){if(m.medianHunger>before.medianHunger)worsened=true;if(worsened&&recovery===null&&m.medianHunger<=before.medianHunger){recovery=f.tick-10*DAY;recoveryAlive=m.alive;}}}}const row={seed,branch,condition,before,after:metrics(f),recoveryMinutes:recovery,recoveryAlive,recoveryNote:recovery!==null?'Recovered after sampled worsening':worsened?'Not recovered':'No sampled worsening'};if(snapshots)row.snapshot=serialize(f);rows.push(row);progress({seed,branch,condition});}}return rows;}
export function aggregate(rows){const groups={};for(const r of rows)(groups[r.branch+' / '+r.condition]??=[]).push(r);return Object.entries(groups).map(([key,rs])=>{const h=rs.filter(r=>r.after.medianHunger!==null);return{key,runs:rs.length,aliveMean:rs.reduce((a,r)=>a+r.after.alive,0)/rs.length,aliveMin:Math.min(...rs.map(r=>r.after.alive)),aliveMax:Math.max(...rs.map(r=>r.after.alive)),hungerMean:h.length?h.reduce((a,r)=>a+r.after.medianHunger,0)/h.length:null,knownMean:rs.reduce((a,r)=>a+r.after.knownSources,0)/rs.length,giftedMean:rs.reduce((a,r)=>a+r.after.gifted,0)/rs.length};});}
